 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: light;
         --page-bg: #f4f7fb;
         --panel-bg: rgba(255, 255, 255, 0.9);
         --panel-border: rgba(15, 23, 42, 0.08);
         --text-main: #0f172a;
         --text-muted: #5b6475;
         --primary: #2563eb;
         --primary-dark: #1d4ed8;
         --field-border: #d6dbe5;
         --field-focus: rgba(37, 99, 235, 0.18);
         --error: #dc2626;
         --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
         --radius-xl: 28px;
         --radius-lg: 18px;
         --radius-md: 14px;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
           sans-serif;
         background:
           radial-gradient(circle at top left, rgba(96, 165, 250, 0.18), transparent 32%),
           radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.14), transparent 28%),
           var(--page-bg);
         color: var(--text-main);
       }

       .page-shell {
         width: min(1080px, calc(100% - 32px));
         margin: 0 auto;
         padding: 56px 0;
       }

       .support-layout {
         display: grid;
         grid-template-columns: 1.1fr 0.9fr;
         gap: 28px;
         align-items: stretch;
       }

       .support-panel,
       .form-card {
         background: var(--panel-bg);
         border: 1px solid var(--panel-border);
         box-shadow: var(--shadow);
         backdrop-filter: blur(12px);
       }

       .support-panel {
         border-radius: var(--radius-xl);
         padding: 40px;
         display: flex;
         flex-direction: column;
         justify-content: space-between;
         overflow: hidden;
         position: relative;
       }

       .support-panel::after {
         content: "";
         position: absolute;
         inset: auto -60px -80px auto;
         width: 220px;
         height: 220px;
         border-radius: 50%;
         background: linear-gradient(135deg, rgba(37, 99, 235, 0.18), rgba(14, 165, 233, 0.04));
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 10px;
         width: fit-content;
         padding: 8px 14px;
         border-radius: 999px;
         background: rgba(37, 99, 235, 0.08);
         color: var(--primary-dark);
         font-size: 0.83rem;
         font-weight: 700;
         letter-spacing: 0.02em;
       }

       h1 {
         margin: 18px 0 14px;
         font-size: clamp(2.2rem, 5vw, 3.6rem);
         line-height: 1;
         letter-spacing: -0.04em;
       }

       .lead {
         margin: 0;
         max-width: 36rem;
         color: var(--text-muted);
         font-size: 1.02rem;
         line-height: 1.7;
       }

       .feature-list {
         display: grid;
         gap: 14px;
         margin: 36px 0 0;
         padding: 0;
         list-style: none;
         position: relative;
         z-index: 1;
       }

       .feature-list li {
         display: flex;
         align-items: center;
         gap: 12px;
         color: #1e293b;
         font-weight: 500;
       }

       .feature-badge {
         width: 34px;
         height: 34px;
         display: inline-flex;
         align-items: center;
         justify-content: center;
         border-radius: 12px;
         background: rgba(15, 23, 42, 0.05);
         color: var(--primary-dark);
         font-size: 1rem;
       }

       .form-card {
         border-radius: var(--radius-xl);
         padding: 32px;
       }

       .form-header h2 {
         margin: 0;
         font-size: 1.55rem;
         letter-spacing: -0.03em;
       }

       .form-header p {
         margin: 10px 0 0;
         color: var(--text-muted);
         line-height: 1.6;
       }

       form {
         margin-top: 28px;
       }

       .form-field {
         margin-bottom: 18px;
       }

       label {
         display: inline-block;
         margin-bottom: 8px;
         font-weight: 600;
         color: #1e293b;
       }

       .required-indicator {
         color: var(--primary-dark);
       }

       input {
         width: 100%;
         border: 1px solid var(--field-border);
         border-radius: var(--radius-md);
         padding: 15px 16px;
         font: inherit;
         color: var(--text-main);
         background: rgba(255, 255, 255, 0.96);
         transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
       }

       input::placeholder {
         color: #94a3b8;
       }

       input:focus {
         outline: none;
         border-color: var(--primary);
         box-shadow: 0 0 0 5px var(--field-focus);
       }

       .helper-text,
       .error-text {
         margin-top: 8px;
         font-size: 0.92rem;
         line-height: 1.5;
       }

       .helper-text {
         color: var(--text-muted);
       }

       .error-text {
         color: var(--error);
         min-height: 1.4em;
       }

       .form-actions {
         margin-top: 26px;
       }

       button {
         width: 100%;
         border: 0;
         border-radius: 999px;
         padding: 15px 22px;
         font: inherit;
         font-weight: 700;
         color: white;
         background: linear-gradient(135deg, var(--primary), #0ea5e9);
         cursor: pointer;
         box-shadow: 0 16px 30px rgba(37, 99, 235, 0.22);
         transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
       }

       button:hover {
         transform: translateY(-1px);
         box-shadow: 0 20px 36px rgba(37, 99, 235, 0.26);
         filter: brightness(1.02);
       }

       button:active {
         transform: translateY(0);
       }

       .success-banner {
         margin-top: 18px;
         border-radius: var(--radius-md);
         padding: 14px 16px;
         background: rgba(34, 197, 94, 0.12);
         color: #166534;
         font-weight: 600;
       }

       @media (max-width: 900px) {
         .support-layout {
           grid-template-columns: 1fr;
         }

         .support-panel,
         .form-card {
           padding: 28px;
         }
